{
  "terraform": {
    "required_version": ">= 1.5.0",
    "required_providers": {
      "aws": {
        "source": "hashicorp/aws"
      },
      "kubernetes": {
        "source": "hashicorp/kubernetes"
      },
      "helm": {
        "source": "hashicorp/helm",
        "version": "~> 2.17"
      }
    }
  },
  "variable": {
    "cluster_role_arn": {
      "type": "string"
    },
    "worker_role_arn": {
      "type": "string"
    },
    "gateway_chart_version": {
      "type": "string"
    },
    "gateway_values_yaml": {
      "type": "string",
      "sensitive": true
    },
    "logs_chart_version": {
      "type": "string"
    },
    "logs_values_yaml": {
      "type": "string",
      "sensitive": true
    },
    "metrics_chart_version": {
      "type": "string"
    },
    "metrics_values_yaml": {
      "type": "string",
      "sensitive": true
    },
    "dashboards_chart_version": {
      "type": "string"
    },
    "dashboards_values_yaml": {
      "type": "string",
      "sensitive": true
    }
  },
  "provider": {
    "aws": {
      "region": "ap-northeast-2"
    },
    "kubernetes": {
      "host": "${aws_eks_cluster.platform.endpoint}",
      "cluster_ca_certificate": "${base64decode(aws_eks_cluster.platform.certificate_authority[0].data)}",
      "exec": [
        {
          "api_version": "client.authentication.k8s.io/v1beta1",
          "command": "aws",
          "args": [
            "eks",
            "get-token",
            "--region",
            "ap-northeast-2",
            "--cluster-name",
            "${aws_eks_cluster.platform.name}"
          ]
        }
      ]
    },
    "helm": {
      "kubernetes": [
        {
          "host": "${aws_eks_cluster.platform.endpoint}",
          "cluster_ca_certificate": "${base64decode(aws_eks_cluster.platform.certificate_authority[0].data)}",
          "exec": [
            {
              "api_version": "client.authentication.k8s.io/v1beta1",
              "command": "aws",
              "args": [
                "eks",
                "get-token",
                "--region",
                "ap-northeast-2",
                "--cluster-name",
                "${aws_eks_cluster.platform.name}"
              ]
            }
          ]
        }
      ]
    }
  },
  "resource": {
    "aws_vpc": {
      "seoul": {
        "cidr_block": "10.42.0.0/16",
        "enable_dns_hostnames": true,
        "enable_dns_support": true
      }
    },
    "aws_internet_gateway": {
      "internet": {
        "vpc_id": "${aws_vpc.seoul.id}"
      }
    },
    "aws_route_table": {
      "public": {
        "vpc_id": "${aws_vpc.seoul.id}"
      },
      "private_a": {
        "vpc_id": "${aws_vpc.seoul.id}"
      },
      "private_c": {
        "vpc_id": "${aws_vpc.seoul.id}"
      }
    },
    "aws_route": {
      "internet": {
        "route_table_id": "${aws_route_table.public.id}",
        "destination_cidr_block": "0.0.0.0/0",
        "gateway_id": "${aws_internet_gateway.internet.id}"
      },
      "egress_a": {
        "route_table_id": "${aws_route_table.private_a.id}",
        "destination_cidr_block": "0.0.0.0/0",
        "nat_gateway_id": "${aws_nat_gateway.egress_a.id}"
      },
      "egress_c": {
        "route_table_id": "${aws_route_table.private_c.id}",
        "destination_cidr_block": "0.0.0.0/0",
        "nat_gateway_id": "${aws_nat_gateway.egress_c.id}"
      }
    },
    "aws_subnet": {
      "public_a": {
        "vpc_id": "${aws_vpc.seoul.id}",
        "availability_zone": "ap-northeast-2a",
        "cidr_block": "10.42.0.0/24",
        "tags": {
          "kubernetes.io/role/elb": "1"
        }
      },
      "private_a": {
        "vpc_id": "${aws_vpc.seoul.id}",
        "availability_zone": "ap-northeast-2a",
        "cidr_block": "10.42.10.0/24",
        "tags": {
          "kubernetes.io/role/internal-elb": "1"
        }
      },
      "public_c": {
        "vpc_id": "${aws_vpc.seoul.id}",
        "availability_zone": "ap-northeast-2c",
        "cidr_block": "10.42.1.0/24",
        "tags": {
          "kubernetes.io/role/elb": "1"
        }
      },
      "private_c": {
        "vpc_id": "${aws_vpc.seoul.id}",
        "availability_zone": "ap-northeast-2c",
        "cidr_block": "10.42.11.0/24",
        "tags": {
          "kubernetes.io/role/internal-elb": "1"
        }
      }
    },
    "aws_eip": {
      "egress_a": {
        "domain": "vpc"
      },
      "egress_c": {
        "domain": "vpc"
      }
    },
    "aws_nat_gateway": {
      "egress_a": {
        "allocation_id": "${aws_eip.egress_a.id}",
        "subnet_id": "${aws_subnet.public_a.id}",
        "depends_on": [
          "aws_internet_gateway.internet"
        ]
      },
      "egress_c": {
        "allocation_id": "${aws_eip.egress_c.id}",
        "subnet_id": "${aws_subnet.public_c.id}",
        "depends_on": [
          "aws_internet_gateway.internet"
        ]
      }
    },
    "aws_route_table_association": {
      "public_a": {
        "route_table_id": "${aws_route_table.public.id}",
        "subnet_id": "${aws_subnet.public_a.id}"
      },
      "private_a": {
        "route_table_id": "${aws_route_table.private_a.id}",
        "subnet_id": "${aws_subnet.private_a.id}"
      },
      "public_c": {
        "route_table_id": "${aws_route_table.public.id}",
        "subnet_id": "${aws_subnet.public_c.id}"
      },
      "private_c": {
        "route_table_id": "${aws_route_table.private_c.id}",
        "subnet_id": "${aws_subnet.private_c.id}"
      }
    },
    "aws_eks_cluster": {
      "platform": {
        "name": "platform",
        "role_arn": "${var.cluster_role_arn}",
        "vpc_config": [
          {
            "subnet_ids": [
              "${aws_subnet.private_a.id}",
              "${aws_subnet.private_c.id}"
            ],
            "endpoint_private_access": true,
            "endpoint_public_access": false
          }
        ],
        "enabled_cluster_log_types": [
          "api",
          "audit",
          "authenticator"
        ]
      }
    },
    "aws_eks_node_group": {
      "workers": {
        "cluster_name": "${aws_eks_cluster.platform.name}",
        "node_group_name": "platform-workers",
        "node_role_arn": "${var.worker_role_arn}",
        "subnet_ids": [
          "${aws_subnet.private_a.id}",
          "${aws_subnet.private_c.id}"
        ],
        "scaling_config": [
          {
            "desired_size": 2,
            "min_size": 2,
            "max_size": 6
          }
        ]
      }
    },
    "kubernetes_namespace_v1": {
      "ingress": {
        "metadata": [
          {
            "name": "ingress"
          }
        ]
      },
      "application": {
        "metadata": [
          {
            "name": "application"
          }
        ]
      },
      "logging": {
        "metadata": [
          {
            "name": "logging"
          }
        ]
      },
      "monitoring": {
        "metadata": [
          {
            "name": "monitoring"
          }
        ]
      }
    },
    "aws_cloudwatch_log_group": {
      "application": {
        "name": "/platform/application",
        "retention_in_days": 30
      }
    },
    "aws_prometheus_workspace": {
      "metrics": {
        "alias": "platform-metrics"
      }
    },
    "aws_efs_file_system": {
      "shared": {
        "encrypted": true,
        "creation_token": "platform-shared"
      }
    },
    "aws_security_group": {
      "efs": {
        "name": "platform-efs",
        "vpc_id": "${aws_vpc.seoul.id}",
        "ingress": [
          {
            "description": "NFS from EKS nodes",
            "from_port": 2049,
            "to_port": 2049,
            "protocol": "tcp",
            "security_groups": [
              "${aws_eks_cluster.platform.vpc_config[0].cluster_security_group_id}"
            ],
            "cidr_blocks": [],
            "ipv6_cidr_blocks": [],
            "prefix_list_ids": [],
            "self": false
          }
        ]
      }
    },
    "aws_efs_mount_target": {
      "zone_a": {
        "file_system_id": "${aws_efs_file_system.shared.id}",
        "subnet_id": "${aws_subnet.private_a.id}",
        "security_groups": [
          "${aws_security_group.efs.id}"
        ]
      },
      "zone_c": {
        "file_system_id": "${aws_efs_file_system.shared.id}",
        "subnet_id": "${aws_subnet.private_c.id}",
        "security_groups": [
          "${aws_security_group.efs.id}"
        ]
      }
    },
    "helm_release": {
      "gateway": {
        "name": "gateway",
        "namespace": "${kubernetes_namespace_v1.ingress.metadata[0].name}",
        "repository": "https://traefik.github.io/charts",
        "chart": "traefik",
        "version": "${var.gateway_chart_version}",
        "values": [
          "${var.gateway_values_yaml}"
        ],
        "depends_on": [
          "aws_eks_node_group.workers"
        ]
      },
      "logs": {
        "name": "logs",
        "namespace": "${kubernetes_namespace_v1.logging.metadata[0].name}",
        "repository": "https://fluent.github.io/helm-charts",
        "chart": "fluent-bit",
        "version": "${var.logs_chart_version}",
        "values": [
          "${var.logs_values_yaml}"
        ],
        "depends_on": [
          "aws_eks_node_group.workers"
        ]
      },
      "metrics": {
        "name": "metrics",
        "namespace": "${kubernetes_namespace_v1.monitoring.metadata[0].name}",
        "repository": "https://open-telemetry.github.io/opentelemetry-helm-charts",
        "chart": "opentelemetry-collector",
        "version": "${var.metrics_chart_version}",
        "values": [
          "${var.metrics_values_yaml}"
        ],
        "depends_on": [
          "aws_eks_node_group.workers"
        ]
      },
      "dashboards": {
        "name": "dashboards",
        "namespace": "${kubernetes_namespace_v1.monitoring.metadata[0].name}",
        "repository": "https://grafana.github.io/helm-charts",
        "chart": "grafana",
        "version": "${var.dashboards_chart_version}",
        "values": [
          "${var.dashboards_values_yaml}"
        ],
        "depends_on": [
          "aws_eks_node_group.workers"
        ]
      }
    }
  }
}
